import{_ as i,l as s,o as e,c as l,v as t,p as n,x as o,d as m,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"拉姆齐商品税","description":"","frontmatter":{"title":"拉姆齐商品税","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ramsey-commodity-tax.md","filePath":"econ/ramsey-commodity-tax.md","lastUpdated":1789023840000}'),E={name:"econ/ramsey-commodity-tax.md"};function h(c,a,A,_,u,B){const r=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="拉姆齐商品税" tabindex="-1">拉姆齐商品税 <a class="header-anchor" href="#拉姆齐商品税" aria-label="Permalink to &quot;拉姆齐商品税&quot;">​</a></h1><div class="epigraph"><p>若不能对个人做一次总付，筹一笔收入的商品税应使各税基的需求按等比例收缩；可分需求下这就是逆弹性法则。</p><footer>—— Ramsey, A Contribution to the Theory of Taxation, Economic Journal, 1927</footer></div><p><a href="/econ/theory-of-second-best">上一课</a>证明：一条切条件锁死，其余第一最佳条件一般不再可欲，并点名 Ramsey 但不写公式。缺口是这个约束最优的解：计划者仍要筹收入 \\(R\\)，<a href="/econ/welfare-theorems">总额税</a>不可用，只能在商品上钉楔子，楔子应如何分布？本课钉逆弹性法则，不重写次优的拉格朗日存在性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>代表性消费者，生产线性（边际成本恒定），政府要 \\(\\sum_i t_i x_i\\ge R\\)，不能对人征 lump-sum。目标是消费者剩余（或间接效用）最大。Ramsey 的一阶条件说：在最优处，各商品的<strong>补偿需求</strong>应大致等比例下降。若需求相互独立，翻译成</p> \\[\\frac{t_i}{1+t_i}\\propto\\frac{1}{\\varepsilon_i}, \\]<p>\\(\\varepsilon_i\\) 为需求弹性绝对值。无弹性的税基税率更高：同样收入，\\(\\Delta q\\) 更小，<a href="/econ/deadweight-loss">无谓损失</a>的 \\(t^2\\) 项更省。这不是「每个市场自己算自己的税」——交叉弹性在时，要用替代矩阵，上一课已经警告过。</p><h3 id="逆弹性不是公平判断" tabindex="-1">逆弹性不是公平判断 <a class="header-anchor" href="#逆弹性不是公平判断" aria-label="Permalink to &quot;逆弹性不是公平判断&quot;">​</a></h3><p>必需品往往无弹性。逆弹性会加重对它们的税，恰恰可能伤穷人。Ramsey 原问题是代表性消费者的效率；Diamond 1975 加上异质与福利权重后，公式多一项分配特征。本课先钉效率特解，不把逆弹性读成规范口号。</p><p><span class="marginnote">Ramsey 原文用的是「无穷小税使各需求等比例减少」，不是先写 \\(1/\\varepsilon\\)。独立需求时二者等价。有闲暇时，闲暇不能直接征税，Corlett–Hague 说：对与闲暇互补的商品多征，以间接税闲暇。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：拟线性或代表性消费者、无纯利润（或利润被税尽）、商品税线性。规划：\\(\\max v(q)\\) s.t. \\((q-p)\\cdot x(q)\\ge R\\)，其中 \\(q\\) 是消费者价，\\(p\\) 是生产者价。一阶条件给出 Ramsey 规则。Diamond–Mirrlees 1971：生产效率仍应保持，中间品不征——扭曲留给最终消费。</p><p>本课不把公式写成「每个市场的 Harberger 三角单独最小化」。三角之间通过替代相连，最优是约束下的一组相对楔子。</p>',13)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20SB%5B%22%E6%AC%A1%E4%BC%98%EF%BC%9A%E6%80%BB%E9%A2%9D%E7%A8%8E%E9%94%81%E6%AD%BB%22%5D%20--%3E%20RAM%5B%22%E7%AD%B9%20R%EF%BC%9A%E9%80%89%E5%95%86%E5%93%81%E7%A8%8E%E5%90%91%E9%87%8F%22%5D%0A%20%20RAM%20--%3E%20EQ%5B%22%E8%A1%A5%E5%81%BF%E9%9C%80%E6%B1%82%E7%AD%89%E6%AF%94%E4%BE%8B%E6%94%B6%E7%BC%A9%22%5D%0A%20%20EQ%20--%3E%20INV%5B%22%E7%8B%AC%E7%AB%8B%E9%9C%80%E6%B1%82%EF%BC%9A%E9%80%86%E5%BC%B9%E6%80%A7%22%5D%0A%20%20RAM%20--%3E%20DM%5B%22%E7%94%9F%E4%BA%A7%E6%95%88%E7%8E%87%EF%BC%9A%E4%B8%AD%E9%97%B4%E5%93%81%E4%B8%8D%E5%BE%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么等比例收缩：公共资金的边际成本 \\(\\lambda\\) 进入每种商品的边际。最优时，多征一单位税造成的边际 DWL，应在各税基上对齐。独立需求下，DWL 的边际与 \\(t\\varepsilon\\) 成正比，对齐就得到逆弹性。交叉需求时，征 \\(i\\) 会移动 \\(j\\) 的税基，对齐必须在矩阵上做。</p><p>这与上一课的 \\(\\mu\\nabla g\\) 是同一修正项：锁死的是「不能对人做总额税」，\\(g\\) 是政府预算。庇古税遇上 Ramsey，最优税率不是单独的 \\(\\mathrm{MD}\\)，还要叠筹款动机。公共品的萨缪尔森条件也要乘上公共资金边际成本，不能直接套第一最佳的 \\(\\sum\\mathrm{MRS}=\\mathrm{MRT}\\)。</p><h3 id="可分偏好可以取消商品税" tabindex="-1">可分偏好可以取消商品税 <a class="header-anchor" href="#可分偏好可以取消商品税" aria-label="Permalink to &quot;可分偏好可以取消商品税&quot;">​</a></h3><p>Atkinson–Stiglitz：若非线性所得税可用，且商品与闲暇弱可分，最优商品税为零——再扭曲商品只叠加伤害。Ramsey 公式的舞台是「所得税工具不够」或「可分失败」。次优的政策清单随可用工具变，不是一张永恒的逆弹性表。</p><p><span class="marginnote">均匀从价税在劳动供给弹性进入后，等价于对工资征税，一般不是 Ramsey 最优。最优要相对价格结构，不是「所有税率相等」的口号。例外是需求的位似加可分。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>异质消费者、逃税、国际贸易（关税当 Ramsey 税）都会改公式。政治约束「某税率为零」本身是又一条 \\(g(x)\\)，应写进规划，而不是先算完再删。也不要把 Ramsey 写成宏观的资本所得税 Chamley–Judd；那是另一条最优税课序。</p><p>市场失灵课序的计划者工具到此：外部性有庇古，公共品有萨缪尔森加 Ramsey 融资。下一课问这个计划者的目标 \\(W\\) 本身能否从个人序数偏好加总出来。</p><p>后课默认：不能一次总付时，商品税按 Ramsey 规则钉相对楔子；独立需求才写成逆弹性；生产效率另保。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>总额税不可用时，商品税应使补偿需求大致等比例收缩。</li><li>独立需求下即逆弹性：无弹性税基税率更高。</li><li>交叉弹性用替代矩阵，不是各市场各自为政。</li><li>可分加非线性所得税时，商品税可以多余。</li><li>出处：Ramsey, <em>Economic Journal</em>, 1927；Diamond and Mirrlees, <em>AER</em>, 1971；Corlett and Hague, <em>RES</em>, 1953。</li></ul>',12))])}const y=i(E,[["render",h]]);export{R as __pageData,y as default};
